   374	mod tests {
   375	    use super::*;
   376	    const TABLE: &str = "provider model context max-out thinking images\nanthropic claude-opus-5 1M 128K yes yes\nanthropic claude-sonnet-5 1M 128K yes yes\nopenai claude-sonnet-5 1M 128K yes yes\ngroq llama-4-fast 128K 8K no no\n";
   377	    #[test]
   378	    fn parses_and_normalizes_specs() {
   379	        assert_eq!(
   380	            parse_spec("anthropic/claude-opus-5:high"),
   381	            ("anthropic".into(), "claude-opus-5".into(), "high".into())
   382	        );
