   386	    fn catalog_exposes_provider_models_with_decimal_and_short_names() {
   387	        let catalog = ModelCatalog::parse(
   388	            "provider model context max-out thinking images\nopenai gpt-5.6 1M 128K yes yes\nmoonshot luna 1M 128K yes yes\nopenai sol 1M 128K no no\n",
   389	        );
   390	        assert_eq!(catalog.entries.len(), 3);
   391	        assert_eq!(
   392	            catalog.resolve("GPT 5.6", "").unwrap().spec(),
   393	            "openai/gpt-5.6"
   394	        );
   395	        assert_eq!(
   396	            catalog.resolve("moonshot/luna", "high").unwrap().spec(),
   397	            "moonshot/luna:high"
   398	        );
   399	        assert_eq!(
   400	            catalog.resolve("openai/sol", "").unwrap().spec(),
   401	            "openai/sol"
   402	        );
   403	        assert!(catalog.resolve("openai/sol", "high").is_err());
