   410	            catalog.resolve("opus five", "").unwrap().spec(),
   411	            "anthropic/claude-opus-5"
   412	        );
   413	        assert!(catalog
   414	            .resolve("sonnet 5", "")
   415	            .unwrap_err()
   416	            .to_string()
   417	            .contains("openai/claude-sonnet-5"));
